if __name__ == "__main__":
    out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "Strings")
    os.makedirs(out, exist_ok=True)
    for i, lang in enumerate(LANGS):
        d = {k: v[i] for k, v in sorted(T.items()) if v[i] is not None}
        with open(os.path.join(out, f"{lang}.json"), "w", encoding="utf-8", newline="\n") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
            f.write("\n")
    print(len(T), "keys ->", ", ".join(LANGS))
